import{_ as e,c as a,o as t,ah as i}from"./chunks/framework.DE7iKuik.js";const A=JSON.parse('{"title":"Web VSCode","frontmatter":{"title":"Web VSCode","createTime":"2025/03/10 14:14:57","permalink":"/article/web-vscode/","cover":"data:image/svg+xml;base64,","tags":["VSCode"],"lastUpdated":"2026-01-22","link":"/posts/web-vscode","layout":"doc","prev":{"text":"VSCode 配置说明","link":"/posts/vscode-setting"},"next":{"text":"Markdown","link":"/posts/markdown"}},"headers":[],"params":{"pkg":"web-vscode"},"relativePath":"posts/web-vscode.md","filePath":"posts/[pkg].md"}'),s={name:"posts/web-vscode.md"};function u(r,M,j,o,d,L){return t(),a("div",null,[...M[0]||(M[0]=[i('<p>Visual Studio Code 网页版提供完全在浏览器中运行的免费零安装 Microsoft Visual Studio Code 体验.</p><p>GitHub: <a href="https://github.com/coder/code-server" target="_blank" rel="noreferrer">https://github.com/coder/code-server</a></p><h2 id="本地项目" tabindex="-1">本地项目 <a class="header-anchor" href="#本地项目" aria-label="Permalink to “本地项目”">​</a></h2><p>访问: <a href="https://vscode.dev/" target="_blank" rel="noreferrer">https://vscode.dev/</a>，直接在 <code>web vscode</code> 中创建新的本地文件或项目、处理现有的本地项目（需要访问本地目录，有浏览器限制）.</p><h2 id="github项目" tabindex="-1">GitHub项目 <a class="header-anchor" href="#github项目" aria-label="Permalink to “GitHub项目”">​</a></h2><p>直接拼接项目地址，访问可进入项目编辑.</p><p><a href="https://vscode.dev/github/%7Borganization%7D/%7Brepo%7D" target="_blank" rel="noreferrer">https://vscode.dev/github/{organization}/{repo}</a></p><p>如: <a href="https://vscode.dev/github/microsoft/vscode" target="_blank" rel="noreferrer">https://vscode.dev/github/microsoft/vscode</a></p><h2 id="远程隧道" tabindex="-1">远程隧道 <a class="header-anchor" href="#远程隧道" aria-label="Permalink to “远程隧道”">​</a></h2><h3 id="下载vscodecli" tabindex="-1">下载VSCodeCLI <a class="header-anchor" href="#下载vscodecli" aria-label="Permalink to “下载VSCodeCLI”">​</a></h3><p><a href="https://code.visualstudio.com/Download" target="_blank" rel="noreferrer">https://code.visualstudio.com/Download</a></p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xvzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vscode_cli_alpine_x64_cli.tar.gz</span></span></code></pre></div><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>执行上一步解压目录中的 <code>code</code> 二进制文件</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./code tunnel --accept-server-license-terms</span></span></code></pre></div><p>根据提示进行注册.</p><h3 id="访问" tabindex="-1">访问 <a class="header-anchor" href="#访问" aria-label="Permalink to “访问”">​</a></h3><p>通过 <code>Tunnel名称</code> 进行访问 <a href="https://vscode.dev/tunnel/%7BTunnel%E5%90%8D%E7%A7%B0%7D" target="_blank" rel="noreferrer">https://vscode.dev/tunnel/{Tunnel名称}</a></p>',19)])])}const c=e(s,[["render",u]]);export{A as __pageData,c as default};
